-- Adriano: import completo de ADRIANO HORAS.xlsx (nov/2025–ago/2026).
-- Datas invertidas (10/10, 17/02, 08/02, 05/01, 05/12…) vão para o dia
-- da aba. 31/03 na aba abril fica em março. Aquecimento R$10 é bônus.
-- Aba agosto A PAGAR = R$ 501,53 (O5): puxa R$ 4,03 de julho.
-- Conferência 26/08: jun R38 (R$1), jul R81 G=10 (não 14), sem
-- aquecimento dia 4 (G=0), sem 3 aparelhos dez com G=0.
begin;

delete from s7ponto.shifts
 where user_id = (select id from s7ponto.profiles where username = 'adriano')
   and source = 'import';
delete from s7ponto.payments
 where user_id = (select id from s7ponto.profiles where username = 'adriano')
   and source = 'import';
delete from s7ponto.bonus_entries
 where user_id = (select id from s7ponto.profiles where username = 'adriano')
   and source = 'import';

-- Tarefas da planilha (não mexem nas dos outros).
select 'Cadastramento', '#3987e5', 18.00, 20, true
 where not exists (select 1 from s7ponto.tasks where name = 'Cadastramento');

select 'Aparelhos', '#d95926', 30.00, 21, true
 where not exists (select 1 from s7ponto.tasks where name = 'Aparelhos');

select 'Financeiro', '#c98500', 18.00, 22, true
 where not exists (select 1 from s7ponto.tasks where name = 'Financeiro');

select 'Disparo', '#199e70', 15.00, 23, true
 where not exists (select 1 from s7ponto.tasks where name = 'Disparo');

select 'Usuários vencidos', '#d55181', 12.00, 24, true
 where not exists (select 1 from s7ponto.tasks where name = 'Usuários vencidos');

select 'Planilha créditos', '#7d9c2f', 12.00, 25, true
 where not exists (select 1 from s7ponto.tasks where name = 'Planilha créditos');

-- Adriano deixa de usar Atendimento; ganha as tarefas da planilha.
delete from s7ponto.task_assignments
 where user_id = (select id from s7ponto.profiles where username = 'adriano');
delete from s7ponto.task_rates
 where user_id = (select id from s7ponto.profiles where username = 'adriano');

select pr.id, t.id
  from s7ponto.profiles pr
  join s7ponto.tasks t on t.name in (
    'Cadastramento','Aparelhos','Financeiro','Disparo',
    'Usuários vencidos','Planilha créditos','Tarefas'
  )
 where pr.username = 'adriano';

select pr.id, t.id, v.rate
  from s7ponto.profiles pr
  join (values
    ('Cadastramento', 18.00),
    ('Aparelhos', 30.00),
    ('Financeiro', 18.00),
    ('Disparo', 15.00),
    ('Usuários vencidos', 12.00),
    ('Planilha créditos', 12.00),
    ('Tarefas', 15.00)
  ) as v(name, rate) on true
  join s7ponto.tasks t on t.name = v.name
 where pr.username = 'adriano';

create temporary table tmp_adr_shift (
  id uuid primary key,
  started_at timestamptz not null,
  ended_at timestamptz not null,
  period text not null,
  note text
) on commit drop;
create temporary table tmp_adr_seg (
  shift_id uuid not null,
  task_name text not null,
  hourly_rate numeric not null,
  started_at timestamptz not null,
  ended_at timestamptz not null,
  period text not null
) on commit drop;



















  id, user_id, company_id, company_name, period, pay_mode,
  started_at, ended_at, source, note
)
select t.id, pr.id, '36ac470d-c5d2-4bc7-afb4-1db3c159e19f', 'S7', t.period, 'hourly',
       t.started_at, t.ended_at, 'import', t.note
  from tmp_adr_shift t
  join s7ponto.profiles pr on pr.username = 'adriano';

  shift_id, task_id, task_name, hourly_rate, period, started_at, ended_at
)
select t.shift_id, tk.id, t.task_name, t.hourly_rate, t.period,
       t.started_at, t.ended_at
  from tmp_adr_seg t
  join s7ponto.tasks tk on tk.name = t.task_name;

